import android.app.*;
import android.content.res.Configuration;
import android.graphics.Color;
import android.graphics.Typeface;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.util.function.*;
import org.json.*;

/** Original Compose headers/rows/switches with editable native configuration forms. */
public final class ApiSettings {
    interface Work{void run()throws Exception;}
    static final class Page {
        final Activity a;final Dialog dialog;final LinearLayout root,body;final int bg,card,fg,muted;
        Page(String title)throws Exception{a=ApiSupport.activity.get();if(a==null)throw new Exception();boolean dark=(a.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;bg=dark?0xff111111:0xfff7f7f7;card=dark?0xff202020:Color.WHITE;fg=dark?0xffeeeeee:0xff141414;muted=dark?0xffaaaaaa:0xff999999;
            dialog=new ApiPageDialog(a);root=ApiUi.column(a);root.setBackgroundColor(bg);ApiNativeViews.owners(root,a);root.setOnApplyWindowInsetsListener((v,insets)->{int b=android.os.Build.VERSION.SDK_INT>=30?insets.getInsets(WindowInsets.Type.systemBars()).bottom:insets.getSystemWindowInsetBottom();v.setPadding(0,0,0,b);return insets;});root.addView(ApiNativeViews.header(a,title,dialog::dismiss),new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(a);scroll.setVerticalScrollBarEnabled(false);body=ApiUi.column(a);body.setPadding(dp(16),dp(12),dp(16),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
        int dp(int n){return ApiUi.dp(a,n);}void gap(){ApiUi.gap(body,20);}
        TextView text(String s){TextView t=ApiUi.text(a,s,14,muted);t.setPadding(dp(16),dp(8),dp(16),dp(8));body.addView(t);return t;}
        EditText input(String label,String value,boolean secret,boolean multiline){text(label);EditText e=new EditText(a);e.setTextSize(16);e.setTextColor(fg);e.setHintTextColor(muted);e.setText(value);e.setHint(secret?"已保存时留空保留；更换地址需重新填写 Key":label);e.setSingleLine(!multiline);e.setInputType(secret?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT|(multiline?InputType.TYPE_TEXT_FLAG_MULTI_LINE:InputType.TYPE_TEXT_VARIATION_URI));e.setTypeface(Typeface.DEFAULT);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);e.setSaveEnabled(false);e.setPadding(dp(16),dp(12),dp(16),dp(12));e.setBackground(ApiUi.background(card,16,a));if(multiline){e.setMinLines(5);e.setGravity(Gravity.TOP);}e.setContentDescription(label);body.addView(e,new LinearLayout.LayoutParams(-1,multiline?-2:dp(52)));return e;}
        void action(String title,Work work)throws Exception{View v=ApiNativeViews.action(a,title,()->{try{work.run();}catch(Exception e){ApiSupport.notice(e instanceof java.io.IOException?e.getMessage():"操作失败，请检查配置后重试。");}},true,card);body.addView(v,new LinearLayout.LayoutParams(-1,dp(48)));}
        void toggle(String label,String pref,boolean defaultValue)throws Exception{final View[] view={null};view[0]=ApiNativeViews.create(a,ApiNativeViews.toggle(label,()->ApiSupport.prefs().getBoolean(pref,defaultValue),value->{ApiSupport.prefs().edit().putBoolean(pref,value).apply();try{ApiNativeViews.update(view[0],ApiNativeViews.toggle(label,()->ApiSupport.prefs().getBoolean(pref,defaultValue),v->{ApiSupport.prefs().edit().putBoolean(pref,v).apply();refreshToggle(view[0],label,pref,defaultValue);}));}catch(Exception ignored){}}));body.addView(view[0],new LinearLayout.LayoutParams(-1,dp(48)));}
        void show(){dialog.setContentView(root);Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setStatusBarColor(bg);w.setNavigationBarColor(bg);if(bg==0xfff7f7f7)w.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}dialog.show();root.requestApplyInsets();}
    }
    static void refreshToggle(View view,String label,String pref,boolean def){try{ApiNativeViews.update(view,ApiNativeViews.toggle(label,()->ApiSupport.prefs().getBoolean(pref,def),value->{ApiSupport.prefs().edit().putBoolean(pref,value).apply();refreshToggle(view,label,pref,def);}));}catch(Exception ignored){}}
    static String pref(String name){return ApiSupport.prefs().getString(name,"");}
    public static void open(){try{Page p=new Page("接口、人设与记忆");TextView active=p.text("");Runnable update=()->{ApiProfiles.Config c=ApiProfiles.active();active.setText("当前聊天："+(c.custom?c.model+"\n"+c.base:"DeepSeek 官方接口")+"\n记忆："+(ApiSupport.prefs().getBoolean("embedding_remote",false)?"高级 Embeddings 接口":"内置离线模型 · 无需配置 Key"));};
        p.action("自定义聊天接口",ApiSettings::chat);p.gap();p.action("切换到 DeepSeek 官方接口",()->{ApiProfiles.official();update.run();ApiContextUi.changed();ApiSupport.notice("已切换，下一条消息生效。");});p.gap();p.action("人设",ApiSettings::persona);p.gap();p.action("向量记忆库",ApiSettings::memory);p.gap();p.action("记忆模型设置",ApiSettings::embedding);
        p.text("接口和人设修改从下一条请求生效。切换聊天接口会把当前分支的历史发送至所填地址。DeepSeek 的充值和余额仍在额度管理中。兼容接口支持 Chat Completions 流式聊天；图片需所选模型支持视觉。原版搜索、语音和工具能力取决于接口，不能通用。");
        Handler h=new Handler(Looper.getMainLooper());Runnable poll=new Runnable(){public void run(){if(p.dialog.isShowing()){update.run();h.postDelayed(this,1000);}}};p.dialog.setOnDismissListener(d->h.removeCallbacks(poll));p.show();poll.run();
    }catch(Exception e){ApiSupport.notice("设置页面打开失败。");}}
    static void chat()throws Exception{Page p=new Page("自定义聊天接口");p.text("兼容 OpenAI Chat Completions。Base URL 填到 /v1 等服务前缀，不包含 /chat/completions。仅支持 HTTPS。保存会启用 API 模式；不会自动向未知地址发送原有 Key。");
        EditText url=p.input("聊天 Base URL",pref("chat_base"),false,false),key=p.input("聊天 API Key","",true,false),model=p.input("聊天模型名称",pref("chat_model"),false,false),limit=p.input("模型上下文上限（token）",Long.toString(ApiSupport.prefs().getLong("chat_limit",128000)),false,false),output=p.input("单次回答上限（token）",Integer.toString(ApiSupport.prefs().getInt("chat_output",8192)),false,false);limit.setInputType(InputType.TYPE_CLASS_NUMBER);output.setInputType(InputType.TYPE_CLASS_NUMBER);p.gap();p.toggle("请求流式用量统计","chat_usage",true);p.text("如果服务不支持 stream_options，可关闭用量统计。深度思考由模型与服务默认行为决定；兼容模式不发送 DeepSeek 专用的搜索和工具参数。");
        p.action("保存并使用该接口",()->{try{ApiProfiles.saveChat(url.getText().toString(),key.getText().toString(),model.getText().toString(),Long.parseLong(limit.getText().toString()),Integer.parseInt(output.getText().toString()));}catch(NumberFormatException e){throw new java.io.IOException("token 上限请填写整数。");}key.setText("");ApiContextUi.changed();ApiSupport.notice("接口已保存，下一条消息生效；尚未进行网络验证。");});p.gap();p.action("清除自定义接口 Key",()->{ApiSupport.prefs().edit().remove("chat_key").putBoolean("custom_active",false).apply();key.setText("");ApiSupport.notice("已清除，并切回 DeepSeek 官方接口。");});p.show();}
    static void persona()throws Exception{Page p=new Page("人设");p.text("作为 API 聊天的系统指令发送，可填写称呼、语气和回答偏好。留空恢复默认。修改会改变下一次请求的系统前缀，可能使缓存暂时降低。");EditText text=p.input("人设内容",pref("persona"),false,true);p.gap();p.action("保存人设",()->{String s=text.getText().toString().trim();if(s.length()>12000)throw new java.io.IOException("人设最多 12,000 个字符。");ApiSupport.prefs().edit().putString("persona",s).apply();ApiContextUi.changed();ApiSupport.notice("人设已保存，下一条消息生效。");});p.show();}
    static void embedding()throws Exception{Page p=new Page("记忆模型设置");TextView state=p.text("");Runnable refresh=()->state.setText(ApiSupport.prefs().getBoolean("embedding_remote",false)?"当前：高级 Embeddings 接口":"当前：内置 BGE 小型中文模型 · 约 0.024B · INT8\n已随 APK 内置，无需下载、无需 Key，向量在手机上生成。");refresh.run();
        p.action("使用内置离线模型（推荐）",()->{ApiMemory.local();refresh.run();ApiSupport.notice("已启用本机模型，正在后台补建索引。");});p.text("离线模式不把文字发送到 Embeddings 服务。聊天时命中的记忆片段会随当前消息发送至聊天接口。模型适合中文语义检索，不能保证每次都记对；可在记忆库修正或删除。切换模型后会重建索引，文字保留。");p.gap();p.text("高级选项：如需其他向量模型，再填写下面三项。保存后会将记忆文字发送至该接口建立索引，可能产生该服务的费用。");
        EditText url=p.input("Embeddings Base URL",pref("embedding_base"),false,false),key=p.input("Embeddings API Key","",true,false),model=p.input("Embeddings 模型名称",pref("embedding_model"),false,false);p.gap();p.action("保存并使用高级向量接口",()->{ApiMemory.configure(url.getText().toString(),key.getText().toString(),model.getText().toString());key.setText("");refresh.run();ApiSupport.notice("已切换高级接口，正在后台建立索引。");});p.show();}
    static void edit(Page parent,JSONObject row)throws Exception{EditText input=new EditText(parent.a);input.setTextSize(16);input.setGravity(Gravity.TOP);input.setMinLines(6);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setText(row==null?"":row.optString("text"));input.setSaveEnabled(false);
        AlertDialog dialog=new AlertDialog.Builder(parent.a).setTitle(row==null?"添加记忆":"编辑记忆").setView(input).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{ApiMemory.put(row==null?null:row.getString("id"),input.getText().toString(),row==null?"":row.optString("session"));dialog.dismiss();ApiSupport.notice("文字已保存，向量会在后台更新。");}catch(Exception e){ApiSupport.notice(e.getMessage());}}));dialog.show();}
    static void memory()throws Exception{Page p=new Page("向量记忆库");p.toggle("自动记录每轮 API 对话","memory_auto",true);p.toggle("聊天时检索跨会话记忆","memory_enabled",true);p.text("自动记录已完成的 API 问答文字，较长回答分段保存，不记录思考过程和图片原始内容。原免费聊天的旧轮次不会自动导入，可手动添加重要内容。同一会话已在上下文内的记录不重复检索。删除聊天不会同时清除记忆。");TextView status=p.text("");EditText search=p.input("搜索记忆文字","",false,false);p.gap();p.action("添加记忆",()->edit(p,null));p.gap();p.action("补建 / 重试向量索引",()->{ApiMemory.reindex();ApiSupport.notice("已排队处理，进度见下方。");});p.gap();
        LinearLayout rows=ApiUi.column(p.a);p.body.addView(rows);final String[] last={""};Runnable update=()->{try{JSONArray list=ApiMemory.list(search.getText().toString());String fingerprint=list.toString();status.setText("本机 "+ApiMemory.count()+" 条 · 索引任务 "+ApiMemory.pending.size()+"\n"+pref("memory_status"));if(fingerprint.equals(last[0]))return;last[0]=fingerprint;rows.removeAllViews();
            if(list.length()==0){rows.addView(ApiUi.text(p.a,"暂无匹配的记忆",16,p.muted));return;}for(int i=0;i<list.length();i++){JSONObject row=list.getJSONObject(i);String s=row.getString("text");String preview=s.substring(0,Math.min(75,s.length())).replace('\n',' ');View item=ApiNativeViews.action(p.a,preview,()->new AlertDialog.Builder(p.a).setTitle("记忆").setMessage(s).setPositiveButton("编辑",(d,w)->{try{edit(p,row);}catch(Exception e){ApiSupport.notice("编辑打开失败。");}}).setNegativeButton("关闭",null).setNeutralButton("删除",(d,w)->new AlertDialog.Builder(p.a).setTitle("删除这条记忆？").setMessage("删除后不再参与后续检索，已有消息携带的片段会保留。").setNegativeButton("取消",null).setPositiveButton("删除",(x,y)->ApiMemory.delete(row.optString("id"))).show()).show(),true,p.card);rows.addView(item,new LinearLayout.LayoutParams(-1,p.dp(56)));ApiUi.gap(rows,8);}
        }catch(Exception e){status.setText("记忆读取失败，请检查本机存储。");}};
        p.gap();p.text("按更新时间显示最多 100 条；可输入关键词筛选。每条可编辑、删除。切换向量模型时旧索引不会混用。");p.action("清空本机记忆库",()->new AlertDialog.Builder(p.a).setTitle("清空全部记忆？").setMessage("这会删除本机记忆文字与向量，不影响聊天记录。自动记录后续对话的开关保持当前设置。").setNegativeButton("取消",null).setPositiveButton("清空",(d,w)->ApiMemory.clear()).show());Handler handler=new Handler(Looper.getMainLooper());Runnable poll=new Runnable(){public void run(){if(p.dialog.isShowing()){update.run();handler.postDelayed(this,1500);}}};p.dialog.setOnDismissListener(d->handler.removeCallbacks(poll));p.show();poll.run();}
}
